mermaid:
---
config:
  flowchart:
    curve: linear
---
graph TD;
	__start__([<p>__start__</p>]):::first
	assemble_context(assemble_context)
	plan(plan)
	adopt_plan(adopt_plan)
	propose(propose)
	execute(execute)
	reflect(reflect)
	finish(finish)
	__end__([<p>__end__</p>]):::last
	__start__ --> assemble_context;
	adopt_plan --> execute;
	assemble_context -.-> adopt_plan;
	assemble_context -.-> plan;
	execute --> reflect;
	plan -.-> execute;
	plan -.-> finish;
	plan -.-> propose;
	reflect -.-> finish;
	reflect -.-> plan;
	finish --> __end__;
	propose --> __end__;
	classDef default fill:#f2f0ff,line-height:1.2
	classDef first fill-opacity:0
	classDef last fill:#bfb6fc
